# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">WRITING AN OPINION / ARGUMENTATIVE ESSAY ON FUTURE TECHNOLOGY (E12.4)</text>\n  <rect x="20" y="45" width="210" height="198" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Introduction Paragraph</text>\n  <text x="32" y="92" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Hook (Attention Grabber):</text>\n  <text x="40" y="108" font-size="10" fill="#1e3a8a">A striking question or general</text>\n  <text x="40" y="122" font-size="10" fill="#1e3a8a">statement about AI / robotics.</text>\n  <text x="32" y="146" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Thesis Statement:</text>\n  <text x="40" y="162" font-size="10" fill="#1e3a8a">Clearly states the writer\'s main</text>\n  <text x="40" y="176" font-size="10" fill="#1e3a8a">argument ("In my opinion, AI</text>\n  <text x="40" y="190" font-size="10" fill="#1e3a8a">will transform healthcare...").</text>\n  <rect x="245" y="45" width="210" height="198" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">2. Body Paragraphs (Pros/Cons)</text>\n  <text x="257" y="92" font-size="10.5" font-weight="bold" fill="#15803d">• Topic Sentence &amp; Examples:</text>\n  <text x="265" y="108" font-size="10" fill="#14532d">First of all, Furthermore, Moreover,</text>\n  <text x="265" y="122" font-size="10" fill="#14532d">For instance, As a result.</text>\n  <text x="257" y="146" font-size="10.5" font-weight="bold" fill="#15803d">• Contrasting Linkers:</text>\n  <text x="265" y="162" font-size="10" fill="#14532d">On the one hand... On the other</text>\n  <text x="265" y="176" font-size="10" fill="#14532d">hand, However, Nevertheless,</text>\n  <text x="265" y="190" font-size="10" fill="#14532d">Despite / In spite of, Whereas.</text>\n  <rect x="470" y="45" width="210" height="198" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. Conclusion Paragraph</text>\n  <text x="482" y="92" font-size="10.5" font-weight="bold" fill="#b45309">• Concluding Transitions:</text>\n  <text x="490" y="108" font-size="10" fill="#78350f">In conclusion, To sum up,</text>\n  <text x="490" y="122" font-size="10" fill="#78350f">All in all, Taking everything</text>\n  <text x="490" y="136" font-size="10" fill="#78350f">into account.</text>\n  <text x="482" y="160" font-size="10.5" font-weight="bold" fill="#b45309">• Final Prediction:</text>\n  <text x="490" y="176" font-size="10" fill="#78350f">Restating the thesis in different</text>\n  <text x="490" y="190" font-size="10" fill="#78350f">words with a future outlook.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">THEME 5: PSYCHOLOGY — MOODS, EMOTIONS AND ADJECTIVES (E12.5)</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">Positive &amp; Empathetic Moods</text>\n  <text x="40" y="95" font-size="11" fill="#14532d">• <tspan font-weight="bold">Cheerful / Joyful / Elated:</tspan> Neşeli, çok mutlu</text>\n  <text x="40" y="118" font-size="11" fill="#14532d">• <tspan font-weight="bold">Optimistic / Hopeful:</tspan> İyimser, umutlu</text>\n  <text x="40" y="141" font-size="11" fill="#14532d">• <tspan font-weight="bold">Serene / Calm / Tranquil:</tspan> Huzurlu, sakin</text>\n  <text x="40" y="164" font-size="11" fill="#14532d">• <tspan font-weight="bold">Empathetic / Compassionate:</tspan> Empatik, şefkatli</text>\n  <text x="40" y="187" font-size="11" fill="#14532d">• <tspan font-weight="bold">Relieved / Grateful:</tspan> Rahatlamış, minnettar</text>\n  <text x="40" y="212" font-size="10.5" font-weight="bold" fill="#15803d">• Idiom: "On cloud nine" / "Over the moon"</text>\n  <rect x="365" y="45" width="310" height="195" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">Challenging &amp; Negative Moods</text>\n  <text x="380" y="95" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Anxious / Apprehensive:</tspan> Kaygılı, endişeli</text>\n  <text x="380" y="118" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Depressed / Melancholic / Gloomy:</tspan> Çökkün</text>\n  <text x="380" y="141" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Frustrated / Irritated / Indignant:</tspan> Öfkeli, bıkkın</text>\n  <text x="380" y="164" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Overwhelmed / Exhausted:</tspan> Bunalmış, tükenmiş</text>\n  <text x="380" y="187" font-size="11" fill="#7f1d1d">• <tspan font-weight="bold">Bewildered / Perplexed:</tspan> Şaşkın, kafası karışık</text>\n  <text x="380" y="212" font-size="10.5" font-weight="bold" fill="#b91c1c">• Idiom: "Feeling blue" / "Down in the dumps"</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">MAKING SUGGESTIONS, GIVING ADVICE &amp; MOOD CHANGE VERBS</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Making Suggestions &amp; Giving Advice</text>\n  <text x="35" y="94" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">You should / ought to / had better + V₁:</tspan></text>\n  <text x="43" y="110" font-size="10" fill="#1e3a8a">"You had better consult a psychologist."</text>\n  <text x="35" y="132" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">If I were you, I would + V₁:</tspan></text>\n  <text x="43" y="148" font-size="10" fill="#1e3a8a">"If I were you, I would take a break."</text>\n  <text x="35" y="170" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">Why don\'t you / we + V₁ ...?</tspan></text>\n  <text x="35" y="190" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">How about / What about + V-ing ...?</tspan></text>\n  <text x="35" y="210" font-size="10.5" fill="#1e3a8a">• <tspan font-weight="bold">I suggest / recommend (that) you (should) + V₁</tspan></text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">Phrasal Verbs &amp; Expressions for Mood</text>\n  <text x="375" y="94" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Cheer up:</tspan> Neşelenmek / neşelendirmek</text>\n  <text x="375" y="116" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Calm down:</tspan> Sakinleşmek, yatışmak</text>\n  <text x="375" y="138" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Let someone down:</tspan> Hayal kırıklığına uğratmak</text>\n  <text x="375" y="160" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Bottle up emotions:</tspan> Duyguları içine atmak</text>\n  <text x="375" y="182" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Cope with / Deal with stress:</tspan> Stresle başa çıkmak</text>\n  <text x="375" y="204" font-size="10.5" fill="#581c87">• <tspan font-weight="bold">Lose one\'s temper:</tspan> Öfke kontrolünü kaybetmek</text>\n  <text x="375" y="224" font-size="10" font-weight="bold" fill="#7e22ce">• Causative feel: "Music makes me feel relaxed."</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
